(() => {
  const founders=[{"id":98000,"name":"Bruce","memory":"Here from the beginning. A window to our world.","src":"data:image/jpeg;base64,"},{"id":98001,"name":"Henry","memory":"Our very good dog. Part of the picture from the beginning.","src":"data:image/svg+xml;base64,"},{"id":98002,"name":"Founding photo 3","memory":"Part of the picture from the beginning.","src":"founding-photo-3.jpg"}];
  async function addFounders(){
    try {
      const images=await Promise.all(founders.map(p=>img(p.src)));
      while(!sourceImages.length || busy) await new Promise(r=>requestAnimationFrame(r));
      founders.forEach((p,i)=>{
        const tile=DATA.tiles.length; DATA.tiles.push(p.src);sourceImages.push(images[i]);
        const person={id:p.id,name:p.name,memory:p.memory,tile,founding:true};people.push(person);
        const row=document.createElement('div');row.className='bank-row';
        const photo=document.createElement('img');photo.src=p.src;photo.alt=p.name+' · Founding photo';
        const label=document.createElement('div');label.textContent=p.name;
        const sub=document.createElement('small');sub.textContent='PP-'+String(p.id).padStart(6,'0')+' · Founding photo';label.append(sub);
        const button=document.createElement('button');button.className='button outline';button.textContent='Find ⌖';button.onclick=()=>locate(person);
        row.append(photo,label,button);document.querySelector('#bank').append(row);
      });
      const banner=document.createElement('div');banner.className='photo-help';
      banner.innerHTML='<strong>Our founding photo collection</strong> · Three real founding photos, kept in every sample portrait. ';
      founders.forEach(p=>{const button=document.createElement('button');button.className='button outline';button.style.margin='6px';button.textContent='Find '+p.name;button.classList.add('founder-button');button.disabled=true;button.onclick=()=>{locate(people.find(x=>x.id===p.id));document.querySelector('#viewport').scrollIntoView({block:'center'});};banner.append(button);});
      document.querySelector('.edition-head').before(banner);
      document.querySelector('#photoBank .sub').textContent='Your three real founding photos, alongside three fictional examples. Use Find to see each photo’s place.';
      document.querySelector('#photoBank .hint').textContent='These three founding photos were contributed directly by the owner. No purchase or customer account is required for these founding photos.';
      document.querySelector('#findSection .hint').textContent='Coordinates are virtual positions inside the picture. Bruce: PP-098000 · Henry: PP-098001 · Founding photo 3: PP-098002. The other three examples are fictional.';
      document.querySelector('.mosaic-explainer .hint').textContent='Concept preview: repeating fictional samples plus Your three real founding photos. No live payments or public submissions.';
      document.querySelector('.preview').textContent='CONCEPT PREVIEW · Sample mosaic with three real founding photos · Sample statistics · No live payments, public uploads or donations';
      document.querySelector('.art-note').textContent=document.querySelector('.art-note').textContent.replace('Bruce and Henry’s two real founding photos','three real founding photos');
      const baseLocate=locate;
      locate=function(person,doZoom=true){baseLocate(person,doZoom);if(person.founding){document.querySelector('#resultName').textContent=person.name+' · Founding photo';document.querySelector('#resultPhoto').alt=person.name+' · Real founding photo';}};
      await render();
      document.querySelectorAll('.founder-button').forEach(b=>b.disabled=false);
      const params=new URLSearchParams(location.hash.slice(1)),p=people.find(p=>p.founding && p.id===Number(params.get('photo')));if(p)locate(p);
    } catch(error) {console.error('Founding photos could not load',error);}
  }
  addFounders();
})();
